// The watch list: the generated data (`garmin.json`) and helpers for the full list of supported
// models („Wszystkie obsługiwane zegarki — 118 modeli”). Pure, no DOM, no i18n. Loaded only with
// the lazy watch check — the Garmin card in the main bundle reads `remember.ts` instead.
import json from './garmin.json';
import type { GarminData, Supported } from './types';

/** Generated by `npm run garmin:watches` from `garmin/manifest.xml` and the Connect IQ SDK device files. */
export const GARMIN = json as GarminData;

/** A supported product by its id (the remembered model, „Połącz zegarek”). */
export const supportedById = (id: string): Supported | undefined => GARMIN.supported.find((s) => s.id === id);

/** Lines in the order people look for them; any other line follows, alphabetically. */
const LINE_ORDER = [
  'Forerunner',
  'Venu',
  'vívoactive',
  'fēnix',
  'epix',
  'Instinct',
  'Enduro',
  'MARQ',
  'Descent',
  'Approach',
  'D2',
  'Legacy',
];

const byName = (a: string, b: string): number => a.localeCompare(b, 'pl', { numeric: true, sensitivity: 'base' });

export interface ListLine {
  series: string;
  /** Each supported product once, by its main name. */
  models: { id: string; name: string }[];
}

/** Every supported product, grouped by line. */
export function supportedByLine(): ListLine[] {
  const lines = new Map<string, ListLine['models']>();
  for (const s of GARMIN.supported) {
    lines.set(s.series, [...(lines.get(s.series) ?? []), { id: s.id, name: s.names[0]! }]);
  }
  const rank = (series: string) => {
    const i = LINE_ORDER.indexOf(series);
    return i < 0 ? LINE_ORDER.length : i;
  };
  return [...lines]
    .sort(([a], [b]) => rank(a) - rank(b) || byName(a, b))
    .map(([series, models]) => ({ series, models: models.sort((a, b) => byName(a.name, b.name)) }));
}
